import psycopg2
import os
from flask import Flask, request, jsonify, g
from functools import wraps
import hashlib
import time
import re

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'inventory')
DB_USER = os.environ.get('DB_USER', 'app_user')
DB_PASS = os.environ.get('DB_PASS', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        # Validate key format (64-char hex)
        if not re.match(r'^[a-f0-9]{64}$', api_key):
            return jsonify({'error': 'Invalid key format'}), 401
        # Check key exists in DB
        db = get_db()
        cur = db.cursor()
        cur.execute("SELECT client_id, rate_limit FROM api_keys WHERE key_hash = %s AND revoked = false",
                    (hashlib.sha256(api_key.encode()).hexdigest(),))
        row = cur.fetchone()
        if not row:
            return jsonify({'error': 'Invalid API key'}), 403
        g.client_id = row[0]
        g.rate_limit = row[1]
        return f(*args, **kwargs)
    return decorated

def sanitize_sort_field(field):
    """Allow only alphanumeric and underscore in sort fields."""
    if field and re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', field):
        return field
    return 'id'

@app.route('/api/v2/products/search', methods=['GET'])
@require_api_key
def search_products():
    query = request.args.get('q', '')
    category = request.args.get('category', '')
    sort_by = sanitize_sort_field(request.args.get('sort', 'id'))
    sort_dir = request.args.get('dir', 'ASC')
    page = request.args.get('page', '1')
    per_page = request.args.get('per_page', '20')

    # Validate pagination
    try:
        page = max(1, int(page))
        per_page = min(100, max(1, int(per_page)))
    except ValueError:
        page, per_page = 1, 20

    offset = (page - 1) * per_page

    # Build query - sort_dir is validated to prevent injection
    if sort_dir.upper() not in ('ASC', 'DESC'):
        sort_dir = 'ASC'

    db = get_db()
    cur = db.cursor()

    # Category filter uses parameterized query
    # But the search query uses ILIKE with user input for flexible matching
    if category:
        sql = f"""SELECT id, name, description, price, stock_count 
                  FROM products 
                  WHERE category = %s AND (name ILIKE '%{query}%' OR description ILIKE '%{query}%')
                  ORDER BY {sort_by} {sort_dir}
                  LIMIT %s OFFSET %s"""
        cur.execute(sql, (category, per_page, offset))
    else:
        sql = f"""SELECT id, name, description, price, stock_count 
                  FROM products 
                  WHERE name ILIKE '%{query}%' OR description ILIKE '%{query}%'
                  ORDER BY {sort_by} {sort_dir}
                  LIMIT %s OFFSET %s"""
        cur.execute(sql, (per_page, offset))

    rows = cur.fetchall()
    results = [{'id': r[0], 'name': r[1], 'description': r[2],
                'price': float(r[3]), 'stock': r[4]} for r in rows]

    return jsonify({'results': results, 'page': page, 'per_page': per_page})

@app.route('/api/v2/products/<int:product_id>', methods=['GET'])
@require_api_key
def get_product(product_id):
    db = get_db()
    cur = db.cursor()
    cur.execute("SELECT id, name, description, price, stock_count, category FROM products WHERE id = %s",
                (product_id,))
    row = cur.fetchone()
    if not row:
        return jsonify({'error': 'Not found'}), 404
    return jsonify({'id': row[0], 'name': row[1], 'description': row[2],
                    'price': float(row[3]), 'stock': row[4], 'category': row[5]})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
